-- REVIEW DRAFT ONLY: hand-prepared from the isolated Prisma model/reference.
-- Not generated by Prisma Migrate and NOT executed or PostgreSQL-verified.
-- Application remains blocked by config.ts. See ../../../docs/migrations.md
-- for structural-rehearsal gates and separately required data-write safeguards.
-- Seven tables / 41 columns. User.name deliberately omitted for the later exercise.
-- Existing task04_test schema only; no schema creation or Task Two operations.

BEGIN;

-- Permit only the two owner-verified database/role pairs. No URL/secret output.
-- Keep the configured dedicated shadow pair: do not admit autogenerated names.
-- Prisma's normal PostgreSQL shadow reset recreates the selected schema using
-- the shadow connection role before replay. The ownership check below is thus
-- compatible with that path; no live reset/replay is claimed by this review.
-- A missing or differently owned schema intentionally fails closed: investigate
-- setup/reset privileges rather than broadening this SQL or the URL guard.
DO LANGUAGE plpgsql $task04_preflight$
BEGIN
    IF NOT (
        (pg_catalog.current_database() = 'stitchtrack_assessment'
            AND CURRENT_USER = 'stitchtrack_task04_test_app')
        OR
        (pg_catalog.current_database() = 'stitchtrack_task04_shadow'
            AND CURRENT_USER = 'stitchtrack_task04_shadow_app')
    ) THEN
        RAISE EXCEPTION 'Task Four migration target/role mismatch' USING ERRCODE = '42501';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM pg_catalog.pg_namespace AS n
        JOIN pg_catalog.pg_roles AS r ON r.oid = n.nspowner
        WHERE n.nspname = 'task04_test' AND r.rolname = CURRENT_USER
    ) THEN
        RAISE EXCEPTION 'Expected existing task04_test schema owned by current role'
            USING ERRCODE = '42501';
    END IF;
    IF pg_catalog.current_setting('server_encoding') <> 'UTF8' THEN
        RAISE EXCEPTION 'Task Four Unicode text checks require UTF8 server encoding';
    END IF;
END;
$task04_preflight$;

-- No IF NOT EXISTS: unexpected pre-existing tables must stop the migration.
CREATE TABLE "task04_test"."User" (
    "id" TEXT NOT NULL,
    "emailCanonical" TEXT NOT NULL,
    "createdAt" TIMESTAMPTZ(3) NOT NULL,
    CONSTRAINT "User_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "User_emailCanonical_nonblank_check" CHECK (
        pg_catalog.btrim("emailCanonical", U&'\0009\000A\000B\000C\000D\0020\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF') <> ''
    )
);

CREATE TABLE "task04_test"."Session" (
    "id" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "tokenDigest" TEXT NOT NULL,
    "createdAt" TIMESTAMPTZ(3) NOT NULL,
    "expiresAt" TIMESTAMPTZ(3) NOT NULL,
    "revokedAt" TIMESTAMPTZ(3),
    CONSTRAINT "Session_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "Session_expiry_check" CHECK ("expiresAt" > "createdAt")
);

CREATE TABLE "task04_test"."PaymentIntent" (
    "id" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "idempotencyKey" TEXT NOT NULL,
    "amount" NUMERIC(18,2) NOT NULL,
    "currency" CHAR(3) NOT NULL,
    "createdAt" TIMESTAMPTZ(3) NOT NULL,
    CONSTRAINT "PaymentIntent_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "PaymentIntent_amount_check" CHECK ("amount" > 0 AND "amount" <> 'NaN'::NUMERIC),
    CONSTRAINT "PaymentIntent_currency_check" CHECK ("currency"::TEXT COLLATE "C" ~ '^[A-Z]{3}$')
);

CREATE TABLE "task04_test"."PaymentAttempt" (
    "id" TEXT NOT NULL,
    "paymentIntentId" TEXT NOT NULL,
    "attemptNo" INTEGER NOT NULL,
    "outcome" TEXT NOT NULL,
    "failureCode" TEXT,
    "startedAt" TIMESTAMPTZ(3) NOT NULL,
    "finishedAt" TIMESTAMPTZ(3),
    CONSTRAINT "PaymentAttempt_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "PaymentAttempt_number_check" CHECK ("attemptNo" > 0),
    CONSTRAINT "PaymentAttempt_outcome_check" CHECK (
        "outcome" IN ('started', 'failed', 'abandoned', 'succeeded')
    ),
    CONSTRAINT "PaymentAttempt_state_fields_check" CHECK (
        ("outcome" = 'started' AND "finishedAt" IS NULL AND "failureCode" IS NULL)
        OR ("outcome" = 'failed' AND "finishedAt" IS NOT NULL AND "failureCode" IS NOT NULL)
        OR ("outcome" IN ('abandoned', 'succeeded') AND "finishedAt" IS NOT NULL AND "failureCode" IS NULL)
    ),
    CONSTRAINT "PaymentAttempt_finish_time_check" CHECK (
        "finishedAt" IS NULL OR "finishedAt" >= "startedAt"
    )
    -- The proposed failureCode allow-list is documented but not approved/enforced.
);

CREATE TABLE "task04_test"."Payment" (
    "id" TEXT NOT NULL,
    "paymentIntentId" TEXT NOT NULL,
    "successfulAttemptId" TEXT NOT NULL,
    "amount" NUMERIC(18,2) NOT NULL,
    "currency" CHAR(3) NOT NULL,
    "paidAt" TIMESTAMPTZ(3) NOT NULL,
    "recordedAt" TIMESTAMPTZ(3) NOT NULL,
    CONSTRAINT "Payment_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "Payment_amount_check" CHECK ("amount" > 0 AND "amount" <> 'NaN'::NUMERIC),
    CONSTRAINT "Payment_currency_check" CHECK ("currency"::TEXT COLLATE "C" ~ '^[A-Z]{3}$')
    -- No invented ordering constraint between reported paidAt and recordedAt.
);

CREATE TABLE "task04_test"."RetrievalDocument" (
    "id" TEXT NOT NULL,
    "ownerUserId" TEXT NOT NULL,
    "sourceKey" TEXT NOT NULL,
    "sourceText" TEXT NOT NULL,
    "contentDigest" TEXT NOT NULL,
    "createdAt" TIMESTAMPTZ(3) NOT NULL,
    CONSTRAINT "RetrievalDocument_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "RetrievalDocument_sourceKey_nonblank_check" CHECK (
        pg_catalog.btrim("sourceKey", U&'\0009\000A\000B\000C\000D\0020\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF') <> ''
    ),
    CONSTRAINT "RetrievalDocument_sourceText_nonblank_check" CHECK (
        pg_catalog.btrim("sourceText", U&'\0009\000A\000B\000C\000D\0020\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF') <> ''
    )
);

CREATE TABLE "task04_test"."RetrievalChunk" (
    "id" TEXT NOT NULL,
    "documentId" TEXT NOT NULL,
    "ordinal" INTEGER NOT NULL,
    "content" TEXT NOT NULL,
    "contentDigest" TEXT NOT NULL,
    "createdAt" TIMESTAMPTZ(3) NOT NULL,
    CONSTRAINT "RetrievalChunk_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "RetrievalChunk_ordinal_check" CHECK ("ordinal" >= 0),
    CONSTRAINT "RetrievalChunk_content_nonblank_check" CHECK (
        pg_catalog.btrim("content", U&'\0009\000A\000B\000C\000D\0020\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF') <> ''
    )
);

-- PostgreSQL places indexes in their qualified parent table's schema; index
-- names themselves cannot be schema-qualified in CREATE INDEX syntax.
-- These 10 UNIQUE indexes plus 7 PK indexes preserve all candidate keys.
CREATE UNIQUE INDEX "User_emailCanonical_key"
    ON "task04_test"."User" USING BTREE ("emailCanonical");
CREATE UNIQUE INDEX "Session_tokenDigest_key"
    ON "task04_test"."Session" USING BTREE ("tokenDigest");
CREATE INDEX "Session_userId_idx"
    ON "task04_test"."Session" USING BTREE ("userId");
CREATE INDEX "Session_expiresAt_idx"
    ON "task04_test"."Session" USING BTREE ("expiresAt");
CREATE UNIQUE INDEX "PaymentIntent_userId_idempotencyKey_key"
    ON "task04_test"."PaymentIntent" USING BTREE ("userId", "idempotencyKey");
CREATE UNIQUE INDEX "PaymentIntent_id_amount_currency_key"
    ON "task04_test"."PaymentIntent" USING BTREE ("id", "amount", "currency");
CREATE UNIQUE INDEX "PaymentAttempt_paymentIntentId_attemptNo_key"
    ON "task04_test"."PaymentAttempt" USING BTREE ("paymentIntentId", "attemptNo");
CREATE UNIQUE INDEX "PaymentAttempt_id_paymentIntentId_key"
    ON "task04_test"."PaymentAttempt" USING BTREE ("id", "paymentIntentId");
CREATE INDEX "PaymentAttempt_startedAt_started_idx"
    ON "task04_test"."PaymentAttempt" USING BTREE ("startedAt")
    WHERE "outcome" = 'started';
CREATE UNIQUE INDEX "Payment_paymentIntentId_key"
    ON "task04_test"."Payment" USING BTREE ("paymentIntentId");
CREATE UNIQUE INDEX "Payment_successfulAttemptId_key"
    ON "task04_test"."Payment" USING BTREE ("successfulAttemptId");
CREATE UNIQUE INDEX "RetrievalDocument_ownerUserId_sourceKey_key"
    ON "task04_test"."RetrievalDocument" USING BTREE ("ownerUserId", "sourceKey");
CREATE UNIQUE INDEX "RetrievalChunk_documentId_ordinal_key"
    ON "task04_test"."RetrievalChunk" USING BTREE ("documentId", "ordinal");

-- All seven FKs target unconditional PK/UNIQUE keys, never the partial index.
ALTER TABLE "task04_test"."Session"
    ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId")
    REFERENCES "task04_test"."User" ("id") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "task04_test"."PaymentIntent"
    ADD CONSTRAINT "PaymentIntent_userId_fkey" FOREIGN KEY ("userId")
    REFERENCES "task04_test"."User" ("id") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "task04_test"."PaymentAttempt"
    ADD CONSTRAINT "PaymentAttempt_paymentIntentId_fkey" FOREIGN KEY ("paymentIntentId")
    REFERENCES "task04_test"."PaymentIntent" ("id") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "task04_test"."Payment"
    ADD CONSTRAINT "Payment_paymentIntentId_amount_currency_fkey" FOREIGN KEY ("paymentIntentId", "amount", "currency")
    REFERENCES "task04_test"."PaymentIntent" ("id", "amount", "currency") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "task04_test"."Payment"
    ADD CONSTRAINT "Payment_successfulAttemptId_paymentIntentId_fkey" FOREIGN KEY ("successfulAttemptId", "paymentIntentId")
    REFERENCES "task04_test"."PaymentAttempt" ("id", "paymentIntentId") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "task04_test"."RetrievalDocument"
    ADD CONSTRAINT "RetrievalDocument_ownerUserId_fkey" FOREIGN KEY ("ownerUserId")
    REFERENCES "task04_test"."User" ("id") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "task04_test"."RetrievalChunk"
    ADD CONSTRAINT "RetrievalChunk_documentId_fkey" FOREIGN KEY ("documentId")
    REFERENCES "task04_test"."RetrievalDocument" ("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- NOT YET IMPLEMENTED: deferred success/receipt consistency triggers, history
-- immutability guards, and the failureCode allow-list. These must precede
